mapper.select:
select e.id, e.emp_no, e.name, e.gender, e.age, e.phone, e.email, e.dept_id, e.position, e.salary, e.hire_date, e.status, e.create_time, d.name as dept_name, u.username as account_username from sys_employee e left join sys_department d on d.id = e.dept_id and d.deleted = 0 left join sys_user u on u.employee_id = e.id and u.deleted = 0
e.deleted = 0
and e.name like concat('%', #{query.name}, '%')
and e.dept_id = #{query.deptId}
and e.status = #{query.status}
order by e.id desc
